export const guideAreas: GuideArea[] = arcs.flatMap((arc) =>
  arc.areas.map(({ id, title }) => ({
    id: `${arc.id}.${id}`,
    title,
    arcId: arc.id,
    state: (arc.id === "disc-1" && (id === "alexandria" || id === "evil-forest" || id === "ice-cavern" || id === "village-of-dali" || id === "cargo-ship" || id === "lindblum" || id === "exploring-lindblum-kingdom" || id === "journey-to-burmecia" || id === "burmecia")) || (arc.id === "disc-2" && (id === "journey-to-treno" || id === "treno" || id === "journey-to-cleyra" || id === "cleyra" || id === "return-to-alexandria" || id === "pinnacle-rocks" || id === "return-to-lindblum" || id === "journey-to-outer-continent" || id === "outer-continent" || id === "magdalene-forest" || id === "conde-petie-mountain-path" || id === "madain-sari" || id === "journey-to-iifa-tree" || id === "iifa-tree" || id === "return-to-madain-sari" || id === "battle-of-iifa-tree")) || (arc.id === "disc-3" && (id === "the-home-front" || id === "card-tournament" || id === "trouble-on-the-home-front" || id === "the-aftermath" || id === "on-the-high-seas" || id === "picking-up-the-trail" || id === "forgotten-continent" || id === "desert-palace" || id === "lost-continent" || id === "aerial-exploration" || id === "ipsens-castle" || id === "breaking-the-seal" || id === "preparing-to-leave" || id === "portal-to-another-world")) || (arc.id === "disc-4" && (id === "return-to-gaia" || id === "second-battle-of-iifa-tree" || id === "memoria" || id === "final-preparations" || id === "the-final-battle")) ? "partial" : "planned",
  })),
);

export type WalkthroughStepKind = "required" | "pickup" | "optional" | "cutoff" | "combat" | "save";

export type WalkthroughStep = {
  id: string;
  kind: WalkthroughStepKind;
  text: string;
  detail?: string;
  objectiveIds?: string[];
};

export type WalkthroughSection = {
  id: string;
  title: string;
  summary?: string;
  sourceIds: string[];
  steps: WalkthroughStep[];
};

export type WalkthroughChapter = {
  areaId: string;
  overview: string;
  timedRouteNote?: string;
  sections: WalkthroughSection[];
};

export type ObjectiveCategory =
  | "story"
  | "exploration"
  | "collection"
  | "side-content"
  | "achievement"
  | "advanced";

export type GoalProfile = "comprehensive" | "achievements" | "excalibur-ii" | "perfect" | "custom";
export type RouteChoice = "standard" | "excalibur-ii" | "advanced-perfect";
export type PlatformChoice =
  | "unselected"
  | "ps1"
  | "steam"
  | "ps4"
  | "xbox"
  | "switch"
  | "ios"
  | "android"
  // Keep broad values readable when restoring early foundation backups.
  | "playstation"
  | "mobile";

export type GameObjective = {
  id: string;
  title: string;
  category: ObjectiveCategory;
  sourceIds: string[];
  chapterIds?: string[];
  achievementPlatforms?: PlatformChoice[];
  profileIds?: GoalProfile[];
  verification: CoverageState;
};

export type MissableClassification =
  | "permanently-missable"
  | "missable-opportunity"
  | "recoverable-later"
  | "limited-quantity"
  | "recommended-now"
  | "mutually-exclusive"
  | "time-sensitive"
  | "conditional"
  | "version-dependent";

export type MissableRecord = {
  id: string;
  objectiveId: string;
  title: string;
  classification: MissableClassification[];
  warningChapterIds?: string[];
  routeChoices?: RouteChoice[];
  consequence: string;
  deadline: string;
  nextAvailability: string | null;
  action: string;
  recovery: string;
  note?: string;
  sourceIds: string[];
  verification: CoverageState;
  severity: "critical" | "high" | "info";
};

